find_rule:
js:
var d = [];
var html = request(input);
var items = pdfa(html, ".module-items&&.module-item, .hl-list-item, .stui-vodlist__item");
for (var i = 0; i < items.length; i++) {
  var item = items[i];
  var title = pdfh(item, ".module-item-title&&Text, .hl-item-title&&Text, .title&&Text") || '';
  var img = pd(item, "img&&data-original||img&&data-src||img&&src", input) || '';
  var url = pd(item, "a&&href", input) || '';
  var desc = pdfh(item, ".module-item-note&&Text, .hl-pic-text&&Text, .pic-text&&Text") || '';
  if (title && url) {
    d.push({
      title: title.trim(),
      desc: desc.trim(),
      pic_url: img ? img + '@Referer=' + input : '',
      url: url,
      col_type: 'movie_3'
    });
  }
}
setResult(d);

