detail_find_rule:
js:
var d = [];
var currentUrl = (typeof MY_URL !== 'undefined' && MY_URL) ? MY_URL : (typeof input !== 'undefined' ? input : '');
var html = request(currentUrl);
var title = pdfh(html, ".video-info-header h1&&Text, .hl-dc-title&&Text, .stui-content__detail .title&&Text") || '';
var cover = pd(html, ".video-cover img&&src, .hl-dc-pic img&&src, .stui-content__thumb img&&src", currentUrl) || '';
var intro = pdfh(html, ".video-info-main&&Text, .hl-content-text&&Text, .stui-content__detail .desc&&Text") || '';
var cleanTitle = title.replace(/^(?:剧名|片名|名称)[：:]\s*/, '').trim();

// 1. 顶部大卡片（注入标准剧名契约，防止 PC 端和移动端历史记录存成纯分集名）
d.push({
  title: '剧名：' + cleanTitle,
  desc: intro.trim(),
  pic_url: cover ? cover + '@Referer=' + currentUrl : '',
  url: currentUrl,
  col_type: 'pic_1_card'
});

// 2. 线路 Tab 提取与选集聚类
var tabNodes = pdfa(html, ".module-tab-items-box .module-tab-item, .hl-tabs li, .stui-pannel__head h3");
var playlistNodes = pdfa(html, ".module-list .module-blocklist, .hl-plays-list, .stui-content__playlist");

if (playlistNodes.length === 0) {
  playlistNodes = pdfa(html, ".module-play-list, .play-list");
}

for (var t = 0; t < playlistNodes.length; t++) {
  var tabName = (tabNodes[t] ? pdfh(tabNodes[t], "Text") : ('线路 ' + (t + 1))) || ('线路 ' + (t + 1));
  d.push({
    title: '【' + tabName.trim() + '】',
    col_type: 'text_1'
  });
  var epLinks = pdfa(playlistNodes[t], "a");
  for (var e = 0; e < epLinks.length; e++) {
    var ep = epLinks[e];
    var epTitle = pdfh(ep, "Text") || ('第' + (e + 1) + '集');
    var epUrl = pd(ep, "a&&href", currentUrl);
    d.push({
      title: epTitle.trim(),
      url: epUrl + '@lazyRule=.js:(() => { return input; })()',
      col_type: 'text_3'
    });
  }
}
setResult(d);

lazy:
js:
var html = request(input);
var playUrl = '';
// 从 MacCMS 内联 player_aaaa 变量中提取播放数据
var playerMatch = html.match(/player_aaaa\s*=\s*({[\s\S]*?})<\/script>/);
if (playerMatch && playerMatch[1]) {
  try {
    var playerConfig = JSON.parse(playerMatch[1]);
    if (playerConfig.url) {
      playUrl = playerConfig.url;
      if (playUrl.indexOf('http') !== 0) {
        playUrl = 'https:' + playUrl;
      }
    }
  } catch (e) {}
}
// 若无直接 JSON，尝试嗅探页面 iframe
if (!playUrl) {
  var iframeSrc = pd(html, ".player-wrapper iframe&&src, #playleft iframe&&src", input);
  if (iframeSrc) {
    var iframeHtml = request(iframeSrc, { headers: { Referer: input } });
    var m3u8Match = iframeHtml.match(/(https?:\/\/[^"'\s]+\.m3u8[^"'\s]*)/);
    if (m3u8Match) {
      playUrl = m3u8Match[1];
    }
  }
}
if (!playUrl) {
  playUrl = input;
}
// 注入标准防盗链注解
playUrl = playUrl + ';{Referer@' + input + '&&User-Agent@PC}';
setResult({ url: playUrl });
